mapper.insert:
INSERT INTO SST1KT (
    CORP_GR
  , TR_YMD
  , FUND_CD
  , TR_CD
  , SJ_CD
  , CHASU
  , TR_SEQ_NO
  , GYEY_SU
  , GYEY_JISU
  , TR_CO_CD
  , SUSU_TR_CO_CD
  , GYEY_AEK
  , IP_USER
  , CUTOFF_GB
) VALUES (
    #{corpGr}
  , #{trYmd}
  , #{fundCd}
  , #{trCd}
  , #{sjCd}
  , NVL(#{chasu}, 1)
  , #{trSeqNo}
  , #{gyeySu, jdbcType=NUMERIC}
  , #{gyeyJisu, jdbcType=NUMERIC}
  , #{trCoCd, jdbcType=VARCHAR}
  , #{susuTrCoCd, jdbcType=VARCHAR}
  , #{gyeyAek, jdbcType=NUMERIC}
  , #{ipUser, jdbcType=VARCHAR}
  , #{cutoffGb, jdbcType=VARCHAR}
)

mapper.update:
UPDATE SST1KT
   SET GYEY_SU       = #{gyeySu, jdbcType=NUMERIC}
     , GYEY_JISU     = #{gyeyJisu, jdbcType=NUMERIC}
     , GYEY_AEK      = #{gyeyAek, jdbcType=NUMERIC}
     , SUSU_TR_CO_CD = #{susuTrCoCd, jdbcType=VARCHAR}
     , IP_USER       = #{ipUser, jdbcType=VARCHAR}
 WHERE CORP_GR       = #{corpGr}
   AND TR_YMD        = #{trYmd}
   AND FUND_CD       = NVL(#{originalFundCd}, #{fundCd})
   AND TR_CD         = #{trCd}
   AND SJ_CD         = NVL(#{originalSjCd}, #{sjCd})
   AND CHASU         = NVL(#{chasu}, 1)
   AND TR_SEQ_NO     = NVL(#{originalTrSeqNo}, #{trSeqNo})

mapper.delete:
DELETE FROM SST1KT
 WHERE CORP_GR   = #{corpGr}
   AND TR_YMD    = #{trYmd}
   AND FUND_CD   = #{fundCd}
   AND TR_CD     = #{trCd}
   AND SJ_CD     = #{sjCd}
   AND CHASU     = NVL(#{chasu}, 1)
   AND TR_SEQ_NO = #{trSeqNo}
